const POR_NOME = new Map(RECINTOS_CONHECIDOS.map((r) => [normalizarNome(r.nome), r]))

export function recintoConhecido(nome: string): RecintoConhecido | undefined {
  return POR_NOME.get(normalizarNome(nome))
}
